        input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr, output.data_ptr<float>(),
        batch_size, in_channels, out_channels, in_h, in_w, out_h, out_w,
        kernel_size, stride, padding, dilation, groups, has_bias);

    return output;
}
"""

